const cfg = $input.item.json;

const BROWSERLESS_URL = cfg.browserless_url; // ex. http://browserless:3000 (réseau Docker interne à n8n) ou http://localhost:3000
const BROWSERLESS_TOKEN = cfg.browserless_token; // le TOKEN passé au conteneur au lancement (docker run ...)
const SHIPSEN_BASE = "https://api.shipsen.com";
const SUPABASE_URL = cfg.supabase_url;
const SUPABASE_SERVICE_ROLE_KEY = cfg.supabase_service_role_key;
// ⚠️ OPENROUTER_API_KEY est ici dans le nœud "Config" pour rester cohérent avec le style des 3
// autres workflows Shipsen (email/mdp/clé Supabase en clair dans un Set node) — mais une clé IA
// facturée à l'usage mérite mieux : remplacez ce champ par un vrai Credential n8n (HTTP Header
// Auth ou credential "OpenAI" pointé sur https://openrouter.ai/api/v1) dès que possible.
const OPENROUTER_API_KEY = cfg.openrouter_api_key;
const AI_MODEL = cfg.ai_model || "moonshotai/kimi-k3"; // slug OpenRouter — changez ici pour tester un autre modèle, aucune autre ligne à toucher

// ⚠️⚠️⚠️ 3 VALEURS À VÉRIFIER MANUELLEMENT AVANT DE LANCER CE WORKFLOW (voir les notes du nœud
// pour la méthode exacte) — je ne les ai PAS vérifiées moi-même, je n'ai pas d'accès à une session
// Shipsen connectée. Les deviner au hasard casserait silencieusement le scraping.
const LOCALSTORAGE_TOKEN_KEY = "TODO_cle_localstorage_a_verifier"; // Application → Local Storage sur app.shipsen.com après connexion manuelle
const DASHBOARD_URL_TEMPLATE = "https://app.shipsen.com/TODO_route_dashboard?warehouse={warehouseId}"; // copier l'URL réelle de la barre d'adresse sur la page du screenshot
const MONTH_FILTER_LABEL = "This Month"; // texte exact du filtre — à activer seulement si le défaut au chargement n'est PAS déjà "This Month"

// Mêmes 4 warehouses que les 3 autres workflows Shipsen (même compte, un seul token API).
const WAREHOUSES = [
  { country: "Mali", currency: "XOF", warehouse: "619ff174286e83d6aa8f60ba" },
  { country: "Guinea", currency: "GNF", warehouse: "61ceeaa3d08e37d6dca5f6b9" },
  { country: "Senegal", currency: "XOF", warehouse: "61cee91cd08e37d6dca5e4fb" },
  { country: "CoteIvoire", currency: "XOF", warehouse: "619ed4e22c5c08be6fcfd977" },
];

function bodyPreview(body) {
  try {
    return JSON.stringify(body).slice(0, 500);
  } catch {
    return String(body).slice(0, 500);
  }
}

// ─── 1. Login API Shipsen (même mécanisme que shipsen-sync.workflow.json) — on récupère le JWT
// via l'endpoint officiel plutôt que de simuler la saisie du formulaire de login dans le
// navigateur : un champ email/password peut changer d'ID CSS, l'API documentée non.
async function shipsenLogin() {
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: `${SHIPSEN_BASE}/users/login`,
    headers: { "Content-Type": "application/json;charset=utf-8" },
    body: { email: cfg.shipsen_email, password: cfg.shipsen_password },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw new Error(`POST /users/login → HTTP ${res.statusCode}: ${bodyPreview(res.body)}`);
  }
  const h = (res.body && res.body.headers) || {};
  const token = h["X-Auth-Token"] || h["x-auth-token"];
  if (!token) throw new Error(`Login OK mais pas de token: ${bodyPreview(res.body)}`);
  return token;
}

// ─── 2. Script exécuté CÔTÉ BROWSERLESS (pas ici) : injecte le token en localStorage, charge le
// dashboard du warehouse, et renvoie le TEXTE BRUT de la page — on laisse l'IA (étape 3) faire le
// tri plutôt que d'extraire avec des sélecteurs CSS fragiles qui cassent au moindre redesign.
function buildPuppeteerScript(dashboardUrl, token) {
  return `
module.exports = async ({ page }) => {
  await page.goto("https://app.shipsen.com/", { waitUntil: "domcontentloaded" });
  await page.evaluate((tok, key) => localStorage.setItem(key, tok), ${JSON.stringify(token)}, ${JSON.stringify(LOCALSTORAGE_TOKEN_KEY)});
  await page.goto(${JSON.stringify(dashboardUrl)}, { waitUntil: "networkidle2" });

  // TODO : si le filtre par défaut au chargement n'est PAS déjà "This Month", décommenter et
  // remplacer par le vrai sélecteur du dropdown de période (inspecté sur le vrai dashboard) :
  // await page.click("SELECTEUR_DROPDOWN_PERIODE_A_REMPLACER");
  // await page.click("text/${MONTH_FILTER_LABEL}");
  // await page.waitForTimeout(1500);

  await page.waitForSelector("body", { timeout: 15000 });
  const text = await page.evaluate(() => document.body.innerText);
  return { data: text, type: "application/json" };
};
`.trim();
}

async function scrapeDashboard(dashboardUrl, token) {
  const script = buildPuppeteerScript(dashboardUrl, token);
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: `${BROWSERLESS_URL}/function?token=${BROWSERLESS_TOKEN}`,
    headers: { "Content-Type": "application/javascript" },
    body: script,
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw new Error(`Browserless /function → HTTP ${res.statusCode}: ${bodyPreview(res.body)}`);
  }
  return typeof res.body === "string" ? res.body : JSON.stringify(res.body);
}

// ─── 3. IA (OpenRouter, modèle configurable via AI_MODEL) : extraction STRICTE — jamais de
// calcul/estimation, uniquement recopier les nombres explicitement visibles dans le texte
// scrappé. temperature=0 pour limiter la variance d'une lecture à l'autre.
const EXTRACTION_SYSTEM_PROMPT = `Tu reçois le texte brut d'une page de dashboard Shipsen (widgets "Confirmation Rate" et "Delivery Rate", période "This Month"). Extrais UNIQUEMENT les valeurs explicitement affichées, sans jamais calculer ni estimer une valeur absente — mets null si un champ n'apparaît pas dans le texte. Réponds STRICTEMENT en JSON, sans texte autour, avec ce schéma exact :
{
  "confirmation_rate": number|null,
  "confirmed_orders": number|null,
  "total_orders": number|null,
  "cancelled_orders": number|null,
  "delivery_rate": number|null,
  "total_shippings": number|null,
  "received": number|null,
  "paid": number|null,
  "cancelled_shipments": number|null,
  "processed": number|null
}`;

async function extractWithAI(pageText) {
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: "https://openrouter.ai/api/v1/chat/completions",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${OPENROUTER_API_KEY}`,
    },
    body: {
      model: AI_MODEL,
      temperature: 0,
      messages: [
        { role: "system", content: EXTRACTION_SYSTEM_PROMPT },
        { role: "user", content: pageText.slice(0, 8000) },
      ],
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw new Error(`OpenRouter → HTTP ${res.statusCode}: ${bodyPreview(res.body)}`);
  }
  const content = (res.body && res.body.choices && res.body.choices[0] && res.body.choices[0].message && res.body.choices[0].message.content) || "";
  try {
    return JSON.parse(content);
  } catch {
    throw new Error(`Réponse IA non-JSON, extraction annulée pour éviter de stocker une valeur inventée: ${content.slice(0, 300)}`);
  }
}

// ─── 4. Boucle sur les 4 warehouses — une erreur sur un pays n'empêche pas les 3 autres ──────
const rows = [];
const errors = [];
const today = new Date().toISOString().slice(0, 10);

let token;
try {
  token = await shipsenLogin.call(this);
} catch (err) {
  return [{ json: { upserted: 0, errors: [{ country: "ALL", message: `Login échoué — ${err.message}` }], finished_at: new Date().toISOString() } }];
}

for (const wh of WAREHOUSES) {
  try {
    const dashboardUrl = DASHBOARD_URL_TEMPLATE.replace("{warehouseId}", wh.warehouse);
    const pageText = await scrapeDashboard.call(this, dashboardUrl, token);
    const extracted = await extractWithAI.call(this, pageText);

    rows.push({
      country: wh.country,
      period_label: "this_month",
      snapshot_date: today,
      confirmation_rate: extracted.confirmation_rate,
      confirmed_orders: extracted.confirmed_orders,
      total_orders: extracted.total_orders,
      cancelled_orders: extracted.cancelled_orders,
      delivery_rate: extracted.delivery_rate,
      total_shippings: extracted.total_shippings,
      received: extracted.received,
      paid: extracted.paid,
      cancelled_shipments: extracted.cancelled_shipments,
      processed: extracted.processed,
      raw_text: pageText.slice(0, 4000),
      model_used: AI_MODEL,
      synced_at: new Date().toISOString(),
    });
  } catch (err) {
    errors.push({ country: wh.country, message: err.message });
  }
}

// ─── 5. Upsert Supabase — clé (country, period_label, snapshot_date) : une ligne PAR JOUR PAR
// PAYS, jamais écrasée silencieusement (historique/audit, voir shipsen_dashboard_snapshot_schema.sql).
let upserted = 0;
if (rows.length > 0) {
  try {
    const res = await this.helpers.httpRequest({
      method: "POST",
      url: `${SUPABASE_URL}/rest/v1/shipsen_dashboard_snapshot?on_conflict=country,period_label,snapshot_date`,
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
        Prefer: "resolution=merge-duplicates,return=minimal",
      },
      body: rows,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new Error(`HTTP ${res.statusCode}: ${bodyPreview(res.body)}`);
    }
    upserted = rows.length;
  } catch (err) {
    errors.push({ country: "SUPABASE_UPSERT", message: err.message });
  }
}

return [{ json: { upserted, errors, finished_at: new Date().toISOString() } }];
